    Driver(const penta_linear_dae_request_v2& request,penta_linear_dae_result_v2& report,Work& w,const Reduction& reduction):q(request),result(report),work(w),r(reduction),jets((reduction.index+1)*reduction.n),offset(reduction.n),offsetDerivative(reduction.n),forcing(reduction.n){}
    void evaluate(double time){work.check();require(result.forcing_evaluations<q.max_evaluations,"Linear DAE forcing evaluation budget reached.");char error[2048]{};++result.forcing_evaluations;work.spend(r.n*(r.index+1));if(q.forcing(q.forcing_context,time,r.index,jets.data(),error,sizeof(error)))throw Error(2,error[0]?error:"Compiled DAE forcing/time jet failed.");for(auto& x:jets){require(std::isfinite(x),"Native DAE forcing jet returned a nonfinite value.");x/=r.scale;require(std::isfinite(x),"Scaled DAE forcing exceeds finite binary64 range.");}forcing=Eigen::Map<const Vector>(jets.data(),r.n);if(!r.index){offset.setZero();offsetDerivative.setZero();}else{const auto count=r.index*r.n;offset=r.P*Eigen::Map<const Vector>(jets.data(),count);offsetDerivative=r.P*Eigen::Map<const Vector>(jets.data()+r.n,count);}require(offset.allFinite()&&offsetDerivative.allFinite(),"Linear DAE consistency reconstruction overflowed.");}
