        if(!reduction.d){const Vector empty;for(std::size_t sample=0;;++sample){const double t=std::min(q.t1,q.t0+sample*q.sample_step);driver.save(t,empty,empty);if(t==q.t1)break;}}
        else{const auto d=reduction.d,storage=static_cast<std::size_t>(samples);std::vector<double> times(storage),values(storage*d),derivatives(storage*d),initialReduced(d),initialDerivative(d);std::vector<uint8_t> algebraic(d,0);penta_dae_request_v1 reduced{};reduced.struct_size=sizeof(reduced);reduced.dimension=d;reduced.initial=z.data();reduced.initial_derivative=zp.data();reduced.algebraic=algebraic.data();reduced.t0=q.t0;reduced.t1=q.t1;reduced.sample_step=q.sample_step;reduced.rtol=q.rtol;reduced.atol=q.atol;reduced.initial_residual_tolerance=q.residual_tolerance;reduced.index_tolerance=q.rank_tolerance;reduced.max_wall_seconds=q.max_wall_seconds;reduced.minimum_event_interval=1e-8;reduced.max_steps=q.max_steps;reduced.max_evaluations=q.max_evaluations;reduced.callback_context=&driver;reduced.residual=Driver::residual;penta_dae_result_v1 report{};report.struct_size=sizeof(report);report.capacity=storage;report.times=times.data();report.values=values.data();report.derivatives=derivatives.data();report.consistent_initial=initialReduced.data();report.consistent_derivative=initialDerivative.data();char detail[2048]{};const auto api=penta_dae_query_v1(PENTA_DAE_ABI_V1);require(api&&api->solve,"Native IDAS version1 driver is unavailable.");const auto status=api->solve(host,&reduced,&report,detail,sizeof(detail));if(status)throw Error(status,driver.failure.empty()?detail:driver.failure);out.steps=report.steps;out.residual_evaluations=report.residual_evaluations;out.jacobian_evaluations=report.jacobian_evaluations;for(std::size_t row=0;row<report.samples;++row)driver.save(times[row],Eigen::Map<const Vector>(values.data()+row*d,d),Eigen::Map<const Vector>(derivatives.data()+row*d,d));}
        out.elapsed_seconds=std::chrono::duration<double>(Clock::now()-work.start).count();message(out.status,sizeof(out.status),"completed_native_constant_pencil_derivative_array_reduction");return 0;
